  const recorded = [];
  const displayed = [];
  watchTransferProgress(feed, frame => displayed.push(frame), frame => recorded.push(frame));
  assert.deepEqual(displayed, [{ loaded: 4 }]);
  assert.deepEqual(recorded, [{ loaded: 4 }]);
}

{
  const resolvers = new Map();
  const feed = createProgressFeed({
    decode(packet) { return new Promise(resolve => resolvers.set(packet, resolve)); },
  });
  const recorded = [];
  const displayed = [];
  watchTransferProgress(feed, frame => displayed.push(frame), frame => recorded.push(frame));
  feed.emit('older');
  feed.emit('newer');
  resolvers.get('newer')({ loaded: 20 });
  await Promise.resolve();
  resolvers.get('older')({ loaded: 10 });
  await Promise.resolve();
  assert.deepEqual(displayed, [{ loaded: 20 }]);
  assert.deepEqual(recorded, [{ loaded: 20 }, { loaded: 10 }]);
}

{
